(146, 3, 'SG 26 - Provincial Environment & Natural Resources Officer', '{\"sections\":{\"core\":{\"standard\":true,\"label\":\"Core Competencies\",\"level\":\"Advanced\",\"rows\":[{\"id\":\"cc1\",\"title\":\"CC1\",\"desc\":\"Sponsors/initiates development of proactive programs promoting DENR values and ethics\"},{\"id\":\"cc2\",\"title\":\"CC2\",\"desc\":\"Builds and shapes DENR service culture and strategic agenda and provides leadership in service delivery through the highest degree of responsibility and competence\"},{\"id\":\"cc3\",\"title\":\"CC3\",\"desc\":\"Inspires others to act at the highest level of virtue, goodness, honor, justness and decency\"},{\"id\":\"cc4\",\"title\":\"CC4\",\"desc\":\"Champions the principle of transparency and accountability in the agency\"},{\"id\":\"cc5\",\"title\":\"CC5\",\"desc\":\"Sponsors development of proactive programs promoting the preservation and conservation of the environment\"}]},\"org\":{\"standard\":true,\"label\":\"Organizational Competencies\",\"level\":\"Advanced\",\"rows\":[{\"id\":\"oc1\",\"title\":\"OC1\",\"desc\":\"Designs and/or sets standards for a written material used within the bureaucracy while demonstrating independence in producing written work\"},{\"id\":\"oc2\",\"title\":\"OC2\",\"desc\":\"Facilitates and influences target audiences such as Heads of the Agency and external partners/clients. Focuses communication on relaying information, building motivation and calling for action\"},{\"id\":\"oc3\",\"title\":\"OC3\",\"desc\":\"Maximizes the use of equipment, office software and applications in performing assigned tasks. Strategizes the method and use of information that adds value to the organization and public sector\"},{\"id\":\"oc4\",\"title\":\"OC4\",\"desc\":\"Formulates plans, programs and policies on the improvement of project management activities\"},{\"id\":\"oc5\",\"title\":\"OC5\",\"desc\":\"Institutionalizes and sustains the practice of CSW in the organization\"}]},\"lead\":{\"standard\