(219, 3, 'SG 9 - Administrative Assistant III', '{\"sections\":{\"core\":{\"standard\":true,\"label\":\"Core Competencies\",\"level\":\"Basic\",\"rows\":[{\"id\":\"cc1\",\"title\":\"CC1 - DISCIPLINE\",\"desc\":\"Practices ethical and professional behaviors\"},{\"id\":\"cc2\",\"title\":\"CC2 - EXCELLENCE\",\"desc\":\"Complies with DENR\'s standards of service delivery\"},{\"id\":\"cc3\",\"title\":\"CC3 - NOBILITY\",\"desc\":\"Demonstrates virtue, goodness, honor, justness and decency at all times\"},{\"id\":\"cc4\",\"title\":\"CC4 - RESPONSIBILITY\",\"desc\":\"Observes the principle of transparency and accountability in the workplace with supervision and guidance\"},{\"id\":\"cc5\",\"title\":\"CC5 - CARING FOR THE ENVIRONMENT AND NATURAL RESOURCES\",\"desc\":\"Has knowledge of concepts and application of preservation and conservation of the environment\"}]},\"org\":{\"standard\":true,\"label\":\"Organizational Competencies\",\"level\":\"Basic\",\"rows\":[{\"id\":\"oc1\",\"title\":\"OC1 - WRITING EFFECTIVELY\",\"desc\":\"Refers to and/or uses existing communication materials or templates to produce own written work\"},{\"id\":\"oc2\",\"title\":\"OC2 - SPEAKING EFFECTIVELY\",\"desc\":\"Effectively delivers messages that simply focus on data, facts or information and requires minimal preparation or can be supported by available communication materials. Focus of communication is to relay information and/or data\"},{\"id\":\"oc3\",\"title\":\"OC3 - TECHNOLOGY LITERACY AND MANAGING INFORMATION\",\"desc\":\"Applies basic technology (office software and equipment) in the performance of the assigned tasks. Collects, organizes and maintains data\"},{\"id\":\"oc4\",\"title\":\"OC4 - PROJECT MANAGEMENT\",\"desc\":\"Assist in project management activities\"},{\"id\":\"oc5\",\"title\":\"OC5 - COMPLETED STAFF WORK (CSW)\",\"desc\":\"Practices basic knowledge of CSW to generate complete, accurate, relevant and timely output\"}]},\"func\":{\"custom\":true,\"label\":\"Functional Competencies\",\"level\":\"Basic\",\"rows\":[{\"id\":\"f1\",\"title\":\"RAS5 - COURIER, POSTAL AND MESSENGERIAL SERVICES\",\"desc\":\"Performs routine courier, postal and messengerial services\"},{\"id\":\"f2\",\"title\":\"RAS6 - CLERICAL/SECRETARIAL/EXECUTIVE ASSISTANCE SKILLS\",\"desc\":\"Undertakes routine clerical and secretarial functions\"},{\"id\":\"f3\",\"title\":\"RFM1 - GENERAL ACCOUNTING\",\"desc\":\"Records, classifies and summarizes DENR\'s financial transactions\"},{\"id\":\"f4\",\"title\":\"RFM2 - BUDGET PREPARATION\",\"desc\":\"Assists in budget preparation activities to determine the DENR\'s financial requirement\"},{\"id\":\"f5\",\"title\":\"RFM3 - BUDGET ADMINISTRATION AND CONTROL\",\"desc\":\"Assists in the preparation of budget allocation of departments/divisions\"},{\"id\":\"f6\",\"title\":\"RFM4 - ORGANIZATION AND MANAGEMENT SYSTEMS IMPROVEMENT\",\"desc\":\"Assists in the conduct of organization and management systems improvement activities\"},{\"id\":\"f7\",\"title\":\"RFM5 - CASH MANAGEMENT\",\"desc\":\"Assists in the discharge of cash management activities\"},{\"id\":\"f8\",\"title\":\"RHR6 - LEARNING NEEDS ASSESSMENT (LNA)\",\"desc\":\"Assists in the conduct of LNA activities\"},{\"id\":\"f9\",\"title\":\"RHR7 - PREPARATION OF LEARNING DESIGN\",\"desc\":\"Assists in the preparation of learning design\"},{\"id\":\"f10\",\"title\":\"RHR8 - LEARNING EVENT MANAGEMENT\",\"desc\":\"Assists in the conduct of learning program management activities\"},{\"id\":\"f11\",\"title\":\"RHR9 - LEARNING EVENT FACILITATION\",\"desc\":\"Assists in facilitating learning events\"},{\"id\":\"f12\",\"title\":\"RHR10 - NETWORK AND LINKAGING WITH HR PARTNERS\",\"desc\":\"Communicates and coordinates with stakeholders/partners\"},{\"id\":\"f13\",\"title\":\"RHR11 - MONITORING AND EVALUATION (M&E) OF LEARNING AND DEVELOPMENT (L&D) PROGRAMS\",\"desc\":\"Assists conduct of learning and development M&E activities\"},{\"id\":\"f14\",\"title\":\"RHR12 - SCHOLARSHIP ADMINISTRATION\",\"desc\":\"Assists in the implementation of scholarship administration activities\"},{\"id\":\"f15\",\"title\":\"RHR13 - HR PLANNING\",\"desc\":\"Assists in HR planning activities\"},{\"id\":\"f16\",\"title\":\"RHR14 - CAREER DEVELOPMENT\",\"desc\":\"Assists in career development activities\"}]}}}', 9, 9, NULL, NULL, 1, '2026-10-28 02:44:38', '2026-10-28 02:52:18'),
